  "command": "python3 << 'EOF'
from research_sdk import Client
import json, time
c = Client()
jobs = json.load(open('/workspace/work/pilot_jobs.json'))
deadline = time.time() + 900
while time.time() < deadline:
    sts = {m: c.status(j)['status'] for m, j in jobs.items()}
    if all(s not in ('queued','running') for s in sts.values()):
        break
    time.sleep(15)
print(sts)
for m, jid in jobs.items():
    res = c.status(jid)
    if res['status'] == 'ok':
        items = res['result']['items']
        json.dump({'model': m, 'items': items}, open(f'/workspace/work/res_pilot_{m[-2:]}.json','w'), indent=1)
print('charged:', c.budget()[0]['charged'])
EOF",
  "description": "Block until pilots complete"
}
